// src/pages/Auth.jsx
import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';

const Auth = () => {
  const [isSignUp, setIsSignUp] = useState(false);
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    password: '',
    confirmPassword: '',
  });
  
  const navigate = useNavigate(); // تم تفعيل التوجيه هنا
  const [error, setError] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
    setError('');
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setIsLoading(true);

    try {
      if (isSignUp) {
        // 1. التحقق من ملء جميع الحقول
        if (!formData.name ||!formData.password || !formData.confirmPassword) {
          setError("Please fill in all fields.");
          setIsLoading(false);
          return;
        }

        // 2. التحقق من الإيميل الجامعي الجزائري العام
        if (!formData.email.endsWith(".dz") || !formData.email.includes("univ")) {
          setError("Access Denied: Please use your official university email (ending in .dz).");
          setIsLoading(false);
          return;
        }

        // 3. تطابق كلمة المرور
        if (formData.password !== formData.confirmPassword) {
          setError("Passwords do not match!");
          setIsLoading(false);
          return;
        }

        // محاكاة إرسال البيانات (يمكنك استبدالها بـ axios لاحقاً)
        await new Promise(resolve => setTimeout(resolve, 1500));
        alert("Sign up successful! You can now sign in.");
        setIsSignUp(false);
        setFormData({ name: '', email: '', password: '', confirmPassword: '' });

      } else {
        // تسجيل الدخول
        if (!formData.email || !formData.password) {
          setError("Please enter your email and password.");
          setIsLoading(false);
          return;
        }

        // محاكاة تسجيل الدخول
        await new Promise(resolve => setTimeout(resolve, 1500));
        
        alert("Sign in successful!"); // تظهر الرسالة للمستخدم
        localStorage.setItem
        // الانتقال التلقائي للـ Dashboard بعد الضغط على OK
        navigate('/dashboard'); 
      }
    } catch (err) {
      console.error("Authentication error:", err);
      setError("An unexpected error occurred. Please try again.");
    } finally {
      setIsLoading(false);
    }
  };

  const styles = {
    container: {
      display: 'flex',
      justifyContent: 'center',
      alignItems: 'center',
      minHeight: '100vh',
      backgroundColor: '#f0f2f5',
      fontFamily: 'Arial, sans-serif',
      padding: '20px'
    },
    authBox: {
      backgroundColor: '#ffffff',
      padding: '40px',
      borderRadius: '12px',
      boxShadow: '0 4px 20px rgba(0, 0, 0, 0.08)',
      width: '100%',
      maxWidth: '450px',
      textAlign: 'center',
    },
    title: {
      marginBottom: '20px',
      color: '#333',
      fontSize: '28px',
      fontWeight: 'bold'
    },
    form: {
      display: 'flex',
      flexDirection: 'column',
      gap: '15px',
    },
    input: {
      padding: '12px 15px',
      border: '1px solid #ddd',
      borderRadius: '8px',
      fontSize: '16px',
      outlineColor: '#c5a3d1'
    },
    button: {
      padding: '12px 20px',
      backgroundColor: '#c5a3d1',
      color: '#fff',
      border: 'none',
      borderRadius: '8px',
      fontSize: '18px',
      cursor: 'pointer',
      marginTop: '10px',
      fontWeight: 'bold',
    },
    buttonDisabled: {
      backgroundColor: '#cccccc',
      cursor: 'not-allowed',
    },
    errorText: {
      backgroundColor: '#fff5f5',
      color: '#dc3545',
      padding: '10px',
      borderRadius: '5px',
      marginBottom: '20px',
      fontSize: '14px',
      border: '1px solid #feb2b2'
    },
    toggleText: {
      marginTop: '25px',
      color: '#555',
      fontSize: '15px',
    },
    toggleLink: {
      color: '#c5a3d1',
      textDecoration: 'none',
      cursor: 'pointer',
      fontWeight: 'bold',
    },
    alertBox: {
      backgroundColor: '#ebf8ff',
      borderLeft: '4px solid #c5a3d1',
      padding: '12px',
      borderRadius: '8px',
      marginBottom: '20px',
      textAlign: 'left',
      display: 'flex',
      alignItems: 'center'
    }
  };

  return (
    <div style={styles.container}>
      <div style={styles.authBox}>
        <h2 style={styles.title}>{isSignUp ? 'Create Account' : 'Sign In'}</h2>

        {isSignUp && (
          <div style={styles.alertBox}>
            <span style={{ fontSize: '20px', marginRight: '10px' }}>ℹ️</span>
            <div>
              <p style={{ fontSize: '13px', color: '#2b6cb0', fontWeight: 'bold', margin: 0 }}>Important Note:</p>
              <p style={{ fontSize: '11px', color: '#2c5282', marginTop: '4px', margin: 0 }}>
                Please use your official University Email (ending in .dz)
              </p>
            </div>
          </div>
        )}

        {error && <p style={styles.errorText}>{error}</p>}

        <form onSubmit={handleSubmit} style={styles.form}>
          {isSignUp && (
            <input
              type="text"
              name="name"
              placeholder="Full Name"
              value={formData.name}
              onChange={handleChange}
              style={styles.input}
              disabled={isLoading}
            />
          )}
          <input
            type="email"
            name="email"
            placeholder="Email Address"
            value={formData.email}
            onChange={handleChange}
            style={styles.input}
            disabled={isLoading}
          />
          <input
            type="password"
            name="password"
            placeholder="Password"
            value={formData.password}
            onChange={handleChange}
            style={styles.input}
            disabled={isLoading}
          />
          {isSignUp && (
            <input
              type="password"
              name="confirmPassword"
              placeholder="Confirm Password"
              value={formData.confirmPassword}
              onChange={handleChange}
              style={styles.input}
              disabled={isLoading}
            />
          )}

          <button 
            type="submit" 
            style={isLoading ? { ...styles.button, ...styles.buttonDisabled } : styles.button} 
            disabled={isLoading}
          >
            {isLoading ? 'Processing...' : (isSignUp ? 'Sign Up' : 'Sign In')}
          </button>
        </form>

        <p style={styles.toggleText}>
          {isSignUp ? "Already have an account?" : "Don't have an account?"}{' '}
          <span
            onClick={() => {
              setIsSignUp(!isSignUp);
              setError('');
              setFormData({ name: '', email: '', password: '', confirmPassword: '' });
            }}
            style={styles.toggleLink}
          >
            {isSignUp ? 'Sign In' : 'Sign Up'}
          </span>
        </p>
      </div>
    </div>
  );
};

export default Auth;
